export function reconcile(events) {
  const seen = new Set();
  const winners = new Map();
  let duplicates = 0;
  let stale = 0;

  for (const event of events) {
    if (seen.has(event.id)) {
      duplicates++;
      continue;
    }
    seen.add(event.id);

    const previous = winners.get(event.account);
    // Each additional distinct event leaves exactly one more nonwinner,
    // whether it loses now or supersedes the previous winner.
    if (previous !== undefined) stale++;
    if (previous === undefined || event.version > previous.version) {
      // Keep deletes as versioned tombstones until output is assembled.
      winners.set(event.account, event);
    }
  }

  const accounts = [...winners.values()]
    .filter(event => event.op === 'set')
    .map(event => ({ account: event.account, balance: event.amount, version: event.version }))
    .sort((a, b) => a.account < b.account ? -1 : a.account > b.account ? 1 : 0);

  return {
    accounts,
    total: accounts.reduce((sum, account) => sum + account.balance, 0),
    duplicates,
    stale,
  };
}

