export function reconcile(events) {
  const seenIds = new Set();
  const winners = new Map();
  let duplicates = 0;
  let stale = 0;

  for (const event of events) {
    // IDs are global, so duplicate removal must happen before account/version
    // reconciliation. In particular, a duplicate cannot create another account.
    if (seenIds.has(event.id)) {
      duplicates += 1;
      continue;
    }
    seenIds.add(event.id);

    const winner = winners.get(event.account);
    if (winner === undefined) {
      winners.set(event.account, event);
    } else if (event.version > winner.version) {
      winners.set(event.account, event);
      stale += 1;
    } else {
      // Lower versions lose, and equal versions retain the earlier event.
      stale += 1;
    }
  }

  const accounts = [];
  for (const event of winners.values()) {
    if (event.op === 'set') {
      accounts.push({
        account: event.account,
        balance: event.amount,
        version: event.version,
      });
    }
  }
  accounts.sort((left, right) =>
    left.account < right.account ? -1 : left.account > right.account ? 1 : 0,
  );

  return {
    accounts,
    total: accounts.reduce((sum, account) => sum + account.balance, 0),
    duplicates,
    stale,
  };
}

export function reconcile(events) {
  const seenIds = new Set();
  const winners = new Map();
  let duplicates = 0;
  let distinct = 0;

  for (const event of events) {
    if (seenIds.has(event.id)) {
      duplicates += 1;
      continue;
    }

    seenIds.add(event.id);
    distinct += 1;

    const winner = winners.get(event.account);
    // Strict comparison deliberately preserves the first distinct event on a tie.
    if (winner === undefined || event.version > winner.version) {
      winners.set(event.account, event);
    }
  }

  const accounts = [];
  for (const event of winners.values()) {
    if (event.op === 'set') {
      accounts.push({
        account: event.account,
        balance: event.amount,
        version: event.version,
      });
    }
  }

  accounts.sort((left, right) =>
    left.account < right.account ? -1 : left.account > right.account ? 1 : 0,
  );

  return {
    accounts,
    total: accounts.reduce((sum, entry) => sum + entry.balance, 0),
    duplicates,
    stale: distinct - winners.size,
  };
}
